const server = createServer((req, res) => { res.end('no') })
server.on('connection', () => { connections++ })
server.listen(0, async () => {
  const port = server.address().port
  const agent = new ProxyAgent(`http://localhost:${port}`)
  const t = setTimeout(() => {
    console.log('TIMEOUT: connections =', connections)
    process.exit(1)
  }, 2000)
  try {
    const res = await request('http://example.com', { dispatcher: agent })
    console.log('ok', res.statusCode)
  } catch (err) {
    console.log('errored:', err.code, err.message, 'connections =', connections)
  }
  clearTimeout(t)
  server.close(); agent.close()
})

